/**
 * Links to a page's sections, the current marked (`design/components/table-of-contents.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table-of-contents.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  agentPress,
  cell,
  derived,
  elementRef,
  jumpToSection,
  mountEffect,
  uniqueId,
  useMember,
  watchEffect,
  watchSections,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/table-of-contents.module.css'

export interface TableOfContentsItem {
  id: string
  label: string
  level?: 1 | 2
}

/** Links to a page's sections, the current marked: the inputs it takes, by the React member's prop names. */
export interface TableOfContentsProps {
  /**
   * One link per section, in the page's order.
   */
  items: TableOfContentsItem[]
  /**
   * The landmark's name, drawn above the list ("On this page").
   */
  label: string
}

/** Links to a page's sections, the current marked. */
@Component({
  selector: 'pm-table-of-contents',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref],
  // prettier-ignore
  template: `<nav
[attr.class]="e1()"
[attr.aria-labelledby]="e2()"
data-member="table-of-contents"
[pmRef]="nav"
><!-- label -->
<p
[attr.class]="e3()"
[attr.id]="e2()"
>{{ e4() }}</p>
<!-- list -->
<ul
[attr.class]="e5()"
>@for (group of e6(); track e7(group)) {<!-- item -->
<li
[attr.class]="e8()"
><!-- link -->
<a
[attr.class]="e9()"
[attr.href]="e10(group)"
[attr.aria-current]="e11(group)"
(click)="h1($event, group)"
>{{ e12(group) }}</a>
@if (e13(group)) {<!-- sublist -->
<ul
[attr.class]="e14(group)"
>@for (child of e15(group); track e16(child)) {<!-- item -->
<li
[attr.class]="e17(group)"
><!-- link -->
<a
[attr.class]="e18(group)"
[attr.href]="e19(group, child)"
[attr.aria-current]="e20(group, child)"
(click)="h2($event, group, child)"
>{{ e21(group, child) }}</a></li>}</ul>}</li>}</ul></nav>`,
})
export class TableOfContents {
  /**
   * One link per section, in the page's order.
   */
  readonly items = input.required<TableOfContentsProps['items']>()
  /**
   * The landmark's name, drawn above the list ("On this page").
   */
  readonly label = input.required<TableOfContentsProps['label']>()
  /**
   * Called with the current section's id, or `null`, each time it changes.
   */
  readonly onCurrentChange = output<string | null>({ alias: 'currentChange' })
  protected readonly $ = useMember({
    events: ['currentChange'],
    props: { items: () => this.items(), label: () => this.label() },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly current = cell(() => null as string | null)
  protected readonly nav = elementRef<HTMLElement>()
  protected readonly labelId = derived(() => `${this.uid}-label`)
  protected readonly groups = derived(() =>
    this.$p.items.reduce(
      (groups, item, at) => {
        const parent = groups[groups.length - 1]
        if (item.level === 2 && parent !== undefined) parent.children.push({ item, at })
        else groups.push({ item, at, children: [] })
        return groups
      },
      [] as {
        item: TableOfContentsItem
        at: number
        children: { item: TableOfContentsItem; at: number }[]
      }[],
    ),
  )
  protected readonly currentAt = derived(() =>
    this.$p.items.findIndex((item) => item.id === this.current.value),
  )
  private release1: (() => void) | undefined
  private release2: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    watchEffect(
      () => this.$p.items.map((item) => item.id).join(' '),
      () => this.effect1(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return styles.nav
  }

  protected e2() {
    return this.labelId.value
  }

  protected e3() {
    return styles.label
  }

  protected e4() {
    return this.$p.label
  }

  protected e5() {
    return styles.list
  }

  e6() {
    return this.groups.value
  }

  protected e7(group: Each<ReturnType<TableOfContents['e6']>>) {
    return `${group.at}:${group.item.id}`
  }

  protected e8() {
    return styles.item
  }

  protected e9() {
    return styles.link
  }

  protected e10(group: Each<ReturnType<TableOfContents['e6']>>) {
    return `#${group.item.id}`
  }

  protected e11(group: Each<ReturnType<TableOfContents['e6']>>) {
    return group.at === this.currentAt.value ? 'location' : undefined
  }

  protected h1($event: MouseEvent, group: Each<ReturnType<TableOfContents['e6']>>): void {
    jumpToSection(this.nav.value, group.item.id, $event)
  }

  protected e12(group: Each<ReturnType<TableOfContents['e6']>>) {
    return group.item.label
  }

  protected e13(group: Each<ReturnType<TableOfContents['e6']>>) {
    return group.children.length > 0
  }

  protected e14(group: Each<ReturnType<TableOfContents['e6']>>) {
    if (!(group.children.length > 0)) return undefined as never
    return styles.sublist
  }

  e15(group: Each<ReturnType<TableOfContents['e6']>>) {
    if (!(group.children.length > 0)) return undefined as never
    return group.children
  }

  protected e16(child: Each<ReturnType<TableOfContents['e15']>>) {
    return `${child.at}:${child.item.id}`
  }

  protected e17(group: Each<ReturnType<TableOfContents['e6']>>) {
    if (!(group.children.length > 0)) return undefined as never
    return styles.item
  }

  protected e18(group: Each<ReturnType<TableOfContents['e6']>>) {
    if (!(group.children.length > 0)) return undefined as never
    return styles.link
  }

  protected e19(
    group: Each<ReturnType<TableOfContents['e6']>>,
    child: Each<ReturnType<TableOfContents['e15']>>,
  ) {
    if (!(group.children.length > 0)) return undefined as never
    return `#${child.item.id}`
  }

  protected e20(
    group: Each<ReturnType<TableOfContents['e6']>>,
    child: Each<ReturnType<TableOfContents['e15']>>,
  ) {
    if (!(group.children.length > 0)) return undefined as never
    return child.at === this.currentAt.value ? 'location' : undefined
  }

  protected h2(
    $event: MouseEvent,
    group: Each<ReturnType<TableOfContents['e6']>>,
    child: Each<ReturnType<TableOfContents['e15']>>,
  ): void {
    if (!(group.children.length > 0)) return
    jumpToSection(this.nav.value, child.item.id, $event)
  }

  protected e21(
    group: Each<ReturnType<TableOfContents['e6']>>,
    child: Each<ReturnType<TableOfContents['e15']>>,
  ) {
    if (!(group.children.length > 0)) return undefined as never
    return child.item.label
  }

  private effect1(): void {
    this.release1?.()
    const ran = watchSections(
      this.nav.value,
      this.$p.items.map((item) => item.id),
      (id) => {
        if (id === this.current.value) return
        this.current.value = id
        this.$.emit(this.onCurrentChange, 'onCurrentChange', id)
      },
    )
    this.release1 = () => {
      ran()
    }
  }

  private effect2(): void {
    this.release2?.()
    const ran = agentMember({
      member: 'TableOfContents',
      element: () => this.nav.value,
      state: () => ({
        current: this.current.value,
        items: this.$p.items
          .filter((item, at) => this.$p.items.findIndex((other) => other.id === item.id) === at)
          .map((item) => ({ id: item.id, label: item.label })),
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) =>
            agentPress(
              this.nav.value?.querySelectorAll('a')[
                this.$p.items.findIndex((item) => item.id === value)
              ],
            ),
        },
      },
    })
    this.release2 = () => {
      ran()
    }
  }
}
